-- REG-07 (26/11, Guillaume) · the watch per entity, as each MSM sets it (AJD MSM 1.6.4, ASJ MSM 1.5.4, ASF MSM 1.5.2), in three
-- families: regulatory / safety / manufacturer. Each source says how it is looked at: read = S.A.M. reads the public page when
-- Compliance launches a round; open = public page S.A.M. cannot read (to open); login = behind a login (to open, signed in);
-- regulation = followed in the Regulation menu (EARs). A page shared by several entities is read once per round.
-- Every stream: every 15 days, Compliance department (CMM). The former shared streams are kept for history, inactive.
alter table watch_sources add column if not exists access text not null default 'open';
alter table watch_sources drop constraint if exists watch_sources_access_check;
alter table watch_sources add constraint watch_sources_access_check check (access in ('read','open','login','regulation'));
alter table watch_sources add column if not exists snapshot jsonb;      -- entries seen at the last reading [{title,url}]
alter table watch_sources add column if not exists read_at timestamptz;
alter table watch_sources add column if not exists read_note text;
alter table watch_sources add column if not exists last_new jsonb;      -- what was new at the last reading

-- the former shared streams: history kept, no more reminders
update tasks set status = 'done' where kind = 'watch_check' and status = 'open' and ref_id in (select id from watch_topics where key in ('compliance','ato_fstd','safety','cessna','dassault','bombardier'));
update watch_topics set active = false where key in ('compliance','ato_fstd','safety','cessna','dassault','bombardier');
